def replace_placeholders(template: str, mapping: Dict[str, str]) -> str:
    return template.format(**mapping)

def _alpha_key(s: str) -> str:
    return s.strip().lower()

def _sort_records(records: List[Dict[str, Any]], day_key: str, alpha_key: str):
    """
    Sorts records primarily by day (None last) and secondarily by alpha string.
    """
    def key_func(r):
        d = r.get(day_key)
        a = _alpha_key(r.get(alpha_key, ""))
        # (HasDay, DayValue, Alpha) -> None days sort after integer days
        return (0, d, a) if d is not None else (1, 0, a)
    records.sort(key=key_func)

def _dedupe_records_by_text(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    seen = set()
    unique = []
    for r in records:
        txt = r.get("text")
        if txt not in seen:
            unique.append(r)
            seen.add(txt)
    return unique

