def build_events_births_deaths_and_stars(data: Dict[str, Any], root: pathlib.Path):
    events_by_decade = defaultdict(lambda: defaultdict(list))
    births_by_decade = defaultdict(lambda: defaultdict(list))
    deaths_by_decade = defaultdict(lambda: defaultdict(list))
    relationships_by_decade = defaultdict(lambda: defaultdict(list))
    stars_by_decade = defaultdict(list)

    # --- Events ---
    for ev in data.get("event", []):
        sd = ev.get("start_date")
