    for d_map in [births_by_decade, deaths_by_decade, relationships_by_decade]:
        for dec in d_map:
            for yr in d_map[dec]:
                d_map[dec][yr] = _dedupe_records_by_text(d_map[dec][yr])

    def star_sort_key(rec):
        y, d, al = rec.get("year", 0), rec.get("day", None), _alpha_key(rec.get("alpha", ""))
        return (y, 0, d, al) if d is not None else (y, 1, 0, al)
    for dec in stars_by_decade:
        stars_by_decade[dec].sort(key=star_sort_key)

    # Conversion to final output structures
    def sort_year_keys(d): return dict(sorted(d.items()))

    ev_out = {dec: sort_year_keys(yrs) for dec, yrs in events_by_decade.items()}
